form = FORM.read_text(encoding='utf-8')
css = CSS.read_text(encoding='utf-8')

editor = replace_once(editor, "const sizeOptions = [\n  ['small', 'Мелкий'],\n  ['normal', 'Обычный'],\n  ['large', 'Крупный'],\n  ['xlarge', 'Очень крупный'],\n] as const;\n", "const sizeOptions = [\n  ['small', 'Мелкий'],\n  ['normal', 'Обычный'],\n  ['large', 'Крупный'],\n  ['xlarge', 'Очень крупный'],\n] as const;\n\nconst customSizeOptions = Array.from(\n  { length: 39 },\n  (_, index) => index + 10,\n);\n\nconst customColorOptions = [\n  '#F2F7F5',\n  '#A9B8B4',\n  '#19D39A',\n  '#59D9B3',\n  '#4BB5E8',\n  '#6F8CFF',\n  '#A985F5',\n  '#E785C7',\n  '#F0C35A',\n  '#F28C52',\n  '#E84949',\n  '#C7D36F',\n] as const;\n\nconst hexColorPattern = /^#[0-9a-f]{6}$/i;\n", 'editor constants')
